          clearedAssistantSeq = latestAssistant(snapshot)?.seq ?? null;
          setOutput("\u7B49\u5F85\u5F53\u524D\u4F1A\u8BDD\u8F93\u51FA\u3002", true);
          setReasoning("");
          setPanelStatus(`${modes[mode].label}\u6A21\u5F0F \xB7 \u63D2\u4EF6\u8F93\u51FA\u5DF2\u6E05\u7A7A`);
